import{_ as i,c as t,o as a,ae as n}from"./chunks/framework.DMK_uHmU.js";const g=JSON.parse('{"title":"AI Card Designer User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Content/card-designer.md","filePath":"Administration/AI-Management/Content/card-designer.md"}'),r={name:"Administration/AI-Management/Content/card-designer.md"};function l(o,e,s,d,u,c){return a(),t("div",null,e[0]||(e[0]=[n('<h1 id="ai-card-designer-user-guide" tabindex="-1">AI Card Designer User Guide <a class="header-anchor" href="#ai-card-designer-user-guide" aria-label="Permalink to &quot;AI Card Designer User Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#ai-card-designer-user-guide">AI Card Designer User Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-the-card-designer">Accessing the Card Designer</a></li><li><a href="#card-designer-interface-overview">Card Designer Interface Overview</a></li><li><a href="#creating-and-editing-cards">Creating and Editing Cards</a><ul><li><a href="#card-content-creation">Card Content Creation</a></li><li><a href="#using-templates">Using Templates</a></li><li><a href="#markdown-editor">Markdown Editor</a></li><li><a href="#live-preview">Live Preview</a></li></ul></li><li><a href="#card-configuration">Card Configuration</a><ul><li><a href="#card-information">Card Information</a></li><li><a href="#publishing-settings">Publishing Settings</a></li><li><a href="#ai-tuning">AI Tuning</a></li></ul></li><li><a href="#interactive-elements">Interactive Elements</a><ul><li><a href="#adding-navigation-buttons">Adding Navigation Buttons</a></li><li><a href="#button-types">Button Types</a></li><li><a href="#button-management">Button Management</a></li></ul></li><li><a href="#display-options">Display Options</a><ul><li><a href="#preview-sizing">Preview Sizing</a></li><li><a href="#device-simulation">Device Simulation</a></li></ul></li><li><a href="#managing-cards">Managing Cards</a><ul><li><a href="#saving-cards">Saving Cards</a></li><li><a href="#deleting-cards">Deleting Cards</a></li></ul></li><li><a href="#best-practices">Best Practices</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The AI Card Designer is a powerful tool that allows you to create rich, interactive content cards for your AI Assistant. Cards are structured content items that appear in AI responses, providing users with formatted information, visual elements, and interactive buttons. This guide explains how to use the Card Designer to create engaging and effective AI content.</p><h2 id="accessing-the-card-designer" tabindex="-1">Accessing the Card Designer <a class="header-anchor" href="#accessing-the-card-designer" aria-label="Permalink to &quot;Accessing the Card Designer&quot;">​</a></h2><p>The Card Designer is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component:</p><ol><li>Navigate to the Content section in the main menu</li><li>Select &quot;Add&quot; and choose &quot;Create a Card&quot;</li><li>Or, select an existing card from the Content Manager to edit it</li></ol><h2 id="card-designer-interface-overview" tabindex="-1">Card Designer Interface Overview <a class="header-anchor" href="#card-designer-interface-overview" aria-label="Permalink to &quot;Card Designer Interface Overview&quot;">​</a></h2><p>The AI Card Designer consists of four main sections:</p><ol><li><strong>Header Bar</strong>: Contains the title, action buttons (Templates, Delete, Done, Save), and description</li><li><strong>Content Preview</strong>: Shows how your card will appear to users, with a live preview that updates as you edit</li><li><strong>Markdown Editor</strong>: The text editor where you create and format your card content</li><li><strong>Configuration Panels</strong>: Right-side panels for card information, publishing settings, and metadata</li></ol><h2 id="creating-and-editing-cards" tabindex="-1">Creating and Editing Cards <a class="header-anchor" href="#creating-and-editing-cards" aria-label="Permalink to &quot;Creating and Editing Cards&quot;">​</a></h2><h3 id="card-content-creation" tabindex="-1">Card Content Creation <a class="header-anchor" href="#card-content-creation" aria-label="Permalink to &quot;Card Content Creation&quot;">​</a></h3><p>Cards are created using Markdown, a simple formatting syntax:</p><ol><li><p><strong>Basic Formatting</strong>:</p><ul><li><strong>Headings</strong>: Use # symbols (# Title, ## Heading, ### Subheading)</li><li><strong>Text Style</strong>: <em>Italics</em> (surround with *), <strong>Bold</strong> (surround with **)</li><li><strong>Lists</strong>: Create with - or numbers (1. 2. 3.)</li><li><strong>Quotes</strong>: Begin lines with &gt;</li><li><strong>Horizontal Lines</strong>: Insert with --- or ___</li></ul></li><li><p><strong>Advanced Elements</strong>:</p><ul><li><strong>Tables</strong>: Create structured data tables</li><li><strong>Links</strong>: Insert clickable URLs</li><li><strong>Images</strong>: Add images</li></ul></li></ol><h3 id="using-templates" tabindex="-1">Using Templates <a class="header-anchor" href="#using-templates" aria-label="Permalink to &quot;Using Templates&quot;">​</a></h3><p>To speed up card creation:</p><ol><li>Click the &quot;Templates&quot; button in the top-right corner</li><li>Choose from two template sources: <ul><li><strong>System Templates</strong>: Pre-built templates provided by the platform</li><li><strong>My Templates</strong>: Your saved custom templates</li></ul></li><li>Select a template from the list</li><li>The editor will populate with the template content</li><li>Customize the template to fit your needs</li></ol><h3 id="markdown-editor" tabindex="-1">Markdown Editor <a class="header-anchor" href="#markdown-editor" aria-label="Permalink to &quot;Markdown Editor&quot;">​</a></h3><p>The markdown editor appears at the bottom of the left column:</p><ol><li><strong>Toolbar</strong>: Contains formatting buttons for common Markdown elements</li><li><strong>Editor Area</strong>: Where you type and edit your content</li><li><strong>Editor Controls</strong>: Options for viewing modes and additional settings</li></ol><p>The editor supports:</p><ul><li>Text formatting (bold, italic, underline)</li><li>Lists (ordered and unordered)</li><li>Headings and subheadings</li><li>Tables and blockquotes</li><li>Links and images</li></ul><h3 id="live-preview" tabindex="-1">Live Preview <a class="header-anchor" href="#live-preview" aria-label="Permalink to &quot;Live Preview&quot;">​</a></h3><p>Above the editor is a live preview showing how your card will appear:</p><ol><li>The preview updates in real-time as you edit</li><li>Shows exactly how users will see the card</li><li>Includes any interactive buttons you&#39;ve added</li><li>Can be resized to simulate different device views</li></ol><h2 id="card-configuration" tabindex="-1">Card Configuration <a class="header-anchor" href="#card-configuration" aria-label="Permalink to &quot;Card Configuration&quot;">​</a></h2><h3 id="card-information" tabindex="-1">Card Information <a class="header-anchor" href="#card-information" aria-label="Permalink to &quot;Card Information&quot;">​</a></h3><p>Configure basic card details in the Card Information panel:</p><ol><li><p><strong>Title</strong>: The headline of your card (required)</p><ul><li>Should be concise and descriptive</li><li>Appears at the top of the card</li></ul></li><li><p><strong>Description</strong>: Optional explanation of the card&#39;s purpose</p><ul><li>Helps with search and discovery</li><li>Does not appear on the card itself</li></ul></li><li><p><strong>Tags</strong>: Add multiple relevant tags</p><ul><li>Type a tag and press Enter to add it</li><li>Select from existing tags or create new ones</li><li>Helps with content organization and discovery</li></ul></li></ol><h3 id="publishing-settings" tabindex="-1">Publishing Settings <a class="header-anchor" href="#publishing-settings" aria-label="Permalink to &quot;Publishing Settings&quot;">​</a></h3><p>Control where and how your card is used:</p><ol><li><p><strong>Topic</strong>: Select a single primary topic</p><ul><li>Choose from predefined topic list</li><li>Used for high-level categorization and reporting</li></ul></li><li><p><strong>Knowledge Bases</strong>: Select which KBs can use this card</p><ul><li>Cards must be associated with at least one knowledge base</li><li>The AI will only use the card when using selected knowledge bases</li><li>Multiple knowledge bases can be selected</li></ul></li></ol><h3 id="ai-tuning" tabindex="-1">AI Tuning <a class="header-anchor" href="#ai-tuning" aria-label="Permalink to &quot;AI Tuning&quot;">​</a></h3><p>Help the AI understand when to show your card:</p><ol><li><strong>AI Tuning Field</strong>: Enter additional keywords and phrases <ul><li>These words don&#39;t appear in the card content</li><li>Help the AI match user questions to this card</li><li>Include synonyms and alternative phrasings</li><li>This improves the accuracy of card suggestions</li></ul></li></ol><h2 id="interactive-elements" tabindex="-1">Interactive Elements <a class="header-anchor" href="#interactive-elements" aria-label="Permalink to &quot;Interactive Elements&quot;">​</a></h2><h3 id="adding-navigation-buttons" tabindex="-1">Adding Navigation Buttons <a class="header-anchor" href="#adding-navigation-buttons" aria-label="Permalink to &quot;Adding Navigation Buttons&quot;">​</a></h3><p>Cards can include interactive buttons for user navigation:</p><ol><li>Click the &quot;Add Button&quot; link below the card preview</li><li>The Button Manager panel will open</li><li>Click &quot;Add Navigation Button to Card&quot; to create a new button</li><li>Configure the button details (described below)</li><li>Add multiple buttons by repeating the process</li></ol><h3 id="button-types" tabindex="-1">Button Types <a class="header-anchor" href="#button-types" aria-label="Permalink to &quot;Button Types&quot;">​</a></h3><p>Four types of buttons are available:</p><ol><li><p><strong>Card</strong>: Links to another card</p><ul><li>Button Value: The name or ID of the destination card</li></ul></li><li><p><strong>Web Link</strong>: Opens an external website</p><ul><li>Button Value: Complete URL (<a href="https://example.com" target="_blank" rel="noreferrer">https://example.com</a>)</li></ul></li><li><p><strong>Prompt</strong>: Sends a predefined query to the AI</p><ul><li>Button Value: The text query to send</li></ul></li><li><p><strong>Document</strong>: Opens a document in the system</p><ul><li>Button Value: The document ID or name</li></ul></li></ol><h3 id="button-management" tabindex="-1">Button Management <a class="header-anchor" href="#button-management" aria-label="Permalink to &quot;Button Management&quot;">​</a></h3><p>Manage your card&#39;s interactive buttons:</p><ol><li><p><strong>Adding</strong>: Click &quot;Add Navigation Button to Card&quot;</p></li><li><p><strong>Configuring</strong>:</p><ul><li>Button Name: Text that appears on the button</li><li>Button Type: Card, Web Link, Prompt, or Document</li><li>Button Value: Destination or action</li></ul></li><li><p><strong>Reordering</strong>: Drag and drop buttons to change their order</p></li><li><p><strong>Removing</strong>: Click the trash icon to delete a button</p></li></ol><h2 id="display-options" tabindex="-1">Display Options <a class="header-anchor" href="#display-options" aria-label="Permalink to &quot;Display Options&quot;">​</a></h2><h3 id="preview-sizing" tabindex="-1">Preview Sizing <a class="header-anchor" href="#preview-sizing" aria-label="Permalink to &quot;Preview Sizing&quot;">​</a></h3><p>Control the preview size to test different viewing contexts:</p><ol><li><p><strong>Height Toggle</strong>: Click the FullScreen button in the speed dial menu</p><ul><li>Toggles between normal height (38vh) and expanded height (78vh)</li><li>Helps visualize how longer cards will appear</li></ul></li><li><p><strong>Width Settings</strong>: Use the speed dial menu to simulate different devices</p></li></ol><h3 id="device-simulation" tabindex="-1">Device Simulation <a class="header-anchor" href="#device-simulation" aria-label="Permalink to &quot;Device Simulation&quot;">​</a></h3><p>Test how your card appears on different devices:</p><ol><li><p><strong>Desktop View</strong>: Default view, full width</p><ul><li>Access by clicking the Computer icon</li></ul></li><li><p><strong>Tablet View</strong>: 768px width</p><ul><li>Access by clicking the Tablet icon</li></ul></li><li><p><strong>Phone View</strong>: 400px width</p><ul><li>Access by clicking the Mobile icon</li><li>Important for testing responsiveness</li></ul></li></ol><h2 id="managing-cards" tabindex="-1">Managing Cards <a class="header-anchor" href="#managing-cards" aria-label="Permalink to &quot;Managing Cards&quot;">​</a></h2><h3 id="saving-cards" tabindex="-1">Saving Cards <a class="header-anchor" href="#saving-cards" aria-label="Permalink to &quot;Saving Cards&quot;">​</a></h3><p>To save your card:</p><ol><li>Click the &quot;Save&quot; button in the top-right corner</li><li>The system will validate required fields</li><li>A success message confirms when the card is saved</li><li>For new cards, you&#39;ll be redirected to the edit view for the saved card</li></ol><h3 id="deleting-cards" tabindex="-1">Deleting Cards <a class="header-anchor" href="#deleting-cards" aria-label="Permalink to &quot;Deleting Cards&quot;">​</a></h3><p>To delete a card:</p><ol><li>Click the &quot;Delete&quot; button in the top-right corner</li><li>A confirmation dialog will appear</li><li>Click &quot;Delete&quot; in the dialog to confirm</li><li>The card will be permanently removed</li><li>You&#39;ll be redirected to the Content Manager</li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For creating effective AI cards:</p><ol><li><p><strong>Clear Structure</strong>:</p><ul><li>Use headings to organize content</li><li>Keep paragraphs short and focused</li><li>Use lists for sequential information</li><li>Include a clear title that summarizes the card&#39;s purpose</li></ul></li><li><p><strong>Visual Appeal</strong>:</p><ul><li>Use formatting to highlight important information</li><li>Include horizontal rules to separate sections</li><li>Don&#39;t overuse bold or italics</li><li>Consider adding relevant images when helpful</li></ul></li><li><p><strong>Interactive Elements</strong>:</p><ul><li>Add buttons for common follow-up actions</li><li>Name buttons with clear action verbs</li><li>Limit to 3-5 buttons per card for clarity</li><li>Ensure button destinations exist and work</li></ul></li><li><p><strong>AI Optimization</strong>:</p><ul><li>Use the AI Tuning field for synonyms and variations</li><li>Include industry-specific terminology</li><li>Think about how users might phrase questions</li><li>Test cards with sample questions</li></ul></li><li><p><strong>Knowledge Base Association</strong>:</p><ul><li>Associate cards with all relevant knowledge bases</li><li>Consider creating specialized versions for different departments</li><li>Review KB assignments when content changes</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Preview not updating</p><ul><li>Check if you&#39;ve toggled the preview mode off</li><li>Try clicking the refresh button</li><li>Ensure your markdown syntax is correct</li></ul><p><strong>Issue</strong>: Cannot save card</p><ul><li>Verify the required Title field is completed</li><li>Check that at least one knowledge base is selected</li><li>Look for error messages in the toast notifications</li></ul><p><strong>Issue</strong>: Buttons not appearing in preview</p><ul><li>Ensure button configuration is complete (name, type, value)</li><li>Save the card and reload if necessary</li><li>Check that the button manager is properly closed</li></ul><p><strong>Issue</strong>: Templates not loading</p><ul><li>Try selecting a different template and then your preferred one</li><li>Refresh the page and try again</li><li>Check your network connection</li></ul><p><strong>Issue</strong>: Card markdown looks different in preview vs. actual use</p><ul><li>Some advanced markdown features may render differently</li><li>Stick to common formatting elements for consistency</li><li>Test your card in the actual AI interface</li></ul><p><strong>Issue</strong>: Button destinations not working</p><ul><li>Verify the button value is correct (URL, card ID, etc.)</li><li>For card links, ensure the destination card exists</li><li>For web links, include the complete URL with https://</li></ul><hr><p>For additional assistance with the AI Card Designer, please contact your system administrator or refer to the platform documentation.</p>',80)]))}const p=i(r,[["render",l]]);export{g as __pageData,p as default};
